GimCorpus.put(140,0,[[1,2,"אָסֹף אָסֵף. לְשׁוֹן ׳כִּלָּיוֹן׳, כְּמוֹ (שופטים יח:כה) ״וְאָסַפְתָּ אֶת נַפְשֶׁךָ״ דְּמִיכָה. וְאָלֶ״ף חֲסֵרָה בְּתֵיבָה שְׁנִיָּה, שֶׁהֲרֵי הָיָה לוֹ לִכְתֹּב ״אֶאֱסֹף״, אֲבָל יֵשׁ כָּאֵלֶּה הַרְבֵּה, כְּמוֹ ״לֹא יָהֵל שָׁם עֲרָבִי״ (ישעיהו יג:כ), שֶׁהוּא כְּמוֹ ״לֹא יֶאֱהַל״.",1,0],[1,3,"וְהַמַּכְשֵׁלוֹת אֶת הָרְשָׁעִים. הֵם הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת.",1,0],[1,4,"אֶת שְׁאָר הַבַּעַל. שֶׁלֹּא תְהֵא שְׁאֵרִית לְזִכְרוֹנוֹ.",1,0],[1,4,"הַכְּמָרִים עִם הַכֹּהֲנִים. ״פַּלְחֵיהוֹן עִם כּוּמְרֵיהֶם״.",2,0],[1,5,"וְאֶת הַנִּשְׁבָּעִים לַה׳. וְחוֹזְרִים וְנִשְׁבָּעִים בְּמַלְכָּם, בַּעֲבוֹדָה זָרָה שֶׁלָּהֶם. עוֹשִׂין עֲבוֹדָה זָרָה עִקָּר, לוֹמַר: אִם אֵין אַתָּה מַאֲמִין בִּשְׁבוּעַת ה׳, הֲרֵינִי נִשְׁבָּע לְךָ בַּעֲבוֹדָה זָרָה.",1,0],[1,7,"הִקְדִּישׁ קְרֻאָיו. זִמֵּן חֵילוֹתָיו לְיוֹם מוֹעֵד.",1,0],[1,8,"מַלְבּוּשׁ נָכְרִי. תַּכְשִׁיטֵי עֲבוֹדָה זָרָה.",1,0],[1,9,"הַדּוֹלֵג עַל הַמִּפְתָּן. תִּרְגֵּם יוֹנָתָן: ״דְּמְהַלְכִין בְּנִימוּסֵי פְלִשְׁתָּאֵי״, שֶׁלֹּא הָיוּ דּוֹרְכִים עַל מִפְתַּן דָּגוֹן, שֶׁנֶּאֱמַר: ״עַל כֵּן לֹא יִדְרְכוּ כֹהֲנֵי דָגוֹן וְגוֹ׳״ (שמואל א ה:ה).",1,0],[1,10,"מִשַּׁעַר הַדָּגִים. תִּרְגֵּם יוֹנָתָן: ״מִתְּרַע נוּנַיָּא״. וְשַׁעַר הָיָה בִּירוּשָׁלַיִם וְכָךְ שְׁמוֹ.",1,0],[1,10,"מִן הַמִּשְׁנֶה. מִשַּׁעַר הָעוֹפוֹת שֶׁהוּא שֵׁנִי לוֹ.",2,0],[1,11,"יֹשְׁבֵי הַמַּכְתֵּשׁ. ״נַחֲלָא דְקִדְרוֹן״, שֶׁעֲמֻקָּה כְּמַכְתֶּשֶׁת זֶה, תִּרְגֵּם יוֹנָתָן. וּמִדְרַשׁ אַגָּדָה: מִשַּׁעַר הַדָּגִים – זוֹ עַכּוֹ הַנְּתוּנָה בְּחֵיקוֹ שֶׁל הַיָּם, שֶׁשָּׁם נְצוֹדִים דָּגִים הַרְבֵּה.",1,0],[1,11,"מִן הַמִּשְׁנֶה. לוֹד, שֶׁהִיא מִשְׁנֶה לִירוּשָׁלַיִם.",2,0],[1,11,"מֵהַגְּבָעוֹת. זוֹ צִפּוֹרִי, שֶׁיּוֹשֶׁבֶת בְּרָאשֵׁי הֶהָרִים כְּצִפּוֹר.",3,0],[1,11,"יֹשְׁבֵי הַמַּכְתֵּשׁ. זוֹ טְבֶרְיָא, שֶׁעֲמוּקָה מִכָּל אֶרֶץ יִשְׂרָאֵל.",4,0],[1,11,"כִּי נִדְמָה כָּל עַם כְּנַעַן. תִּרְגֵּם יוֹנָתָן: ״אֲרֵי אֲתַר כָּל עַמָּא דְּדָמֵי עוֹבָדֵיהוֹן לְעוֹבְדֵי עַמָּא דְאַרְעָא דִכְנָעַן״.",5,0],[1,11,"כָּל נְטִילֵי כֶסֶף. ״כָּל עֲתִּירֵי נִכְסַיָּא״ טְעוּנֵי מַשָּׂא כֶּסֶף וְזָהָב, כְּמוֹ (משלי כז:ג) ״כֹּבֶד הָאֶבֶן וְנֵטֶל הַחוֹל״, לְשׁוֹן ׳מַשָּׂא׳.",6,0],[1,12,"אֲחַפֵּשׂ אֶת יְרוּשָׁלַ͏ִם בַּנֵּרוֹת. אֲדַקְדֵּק בַּעֲוֹנוֹתֵיהֶם.",1,0],[1,12,"הַקֹּפְאִים. הַצָּפִים עַל שִׁמְרֵיהֶם. ״וַיָּצֶף הַבַּרְזֶל״ (מלכים ב ו:ו) מְתַרְגְּמִינַן: ״וּקְפָא פַרְזְלָא״.",2,0],[1,12,"הָאֹמְרִים בִּלְבָבָם לֹא יֵיטִיב ה׳. לְעוֹשֵׂי רְצוֹנוֹ.",3,0],[1,12,"וְלֹא יָרֵעַ. לְעוֹבְרֵי רְצוֹנוֹ.",4,0],[1,14,"מַר צֹרֵחַ שָׁם גִּבּוֹר. הַגִּבּוֹר יִצְרַח שָׁם בְּקוֹל מַר.",1,0],[1,15,"יוֹם שׁוֹאָה. לְשׁוֹן ׳שִׁמָּמוֹן׳.",1,0],[1,15,"וּמְשׁוֹאָה. שִׁמָּמוֹן יוֹתֵר.",2,0],[1,17,"וַהֲצֵרֹתִי לָאָדָם. לְיִשְׂרָאֵל הַקְּרוּיִים אָדָם.",1,0],[1,17,"וּלְחֻמָּם. בְּשָׂרָם. וּלְשׁוֹן עַרְבִי, בָּשָׂר קוֹרִין ׳אַל לַחַם׳.",2,0],[1,17,"כַּגְּלָלִים. רְעִי.",3,0],[2,1,"הִתְקוֹשְׁשׁוּ. הִתְלַקְּטוּ וְאִסְפוּ יַחַד, כְּמוֹ ״לְקֹשֵׁשׁ קַשׁ״ (שמות ה:יב).",1,0],[2,1,"וָקוֹשּׁוּ. מַעֲשֵׂיכֶם. הַשְׁווּ מַעֲשֵׂיכֶם לְדַעַת קוֹנְכֶם. וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה דָּרְשׁוּ: קַשֵּׁט עַצְמְךָ וְאַחַר כָּךְ קַשֵּׁט אֲחֵרִים. עָשׂוּ שְׁנֵיהֶם לְשׁוֹן ׳הֶקֵּשׁ׳, אָדָם הַמַּשְׁוֶה עַצְמוֹ וּמְיַשֵּׁר דַּרְכּוֹ.",2,0],[2,1,"הַגּוֹי לֹא נִכְסָף. תִּרְגֵּם יוֹנָתָן: ״דְּלָא חֲמַד לְמֵיתַב לְאוֹרָיְתָא״.",3,0],[2,2,"בְּטֶרֶם לֶדֶת חֹק. לִפְנֵי בֹּא הַגְּזֵירָה.",1,0],[2,2,"כְּמֹץ עָבַר. הֲרֵי זֶה מִקְרָא קָצָר, כְּמֹץ הָעוֹבֵר מִלִּפְנֵי רוּחַ, וּכְעָשָׁן הָעוֹבֵר מִלִּפְנֵי הַשֶּׁמֶשׁ. וְזֶהוּ תַּרְגּוּמוֹ שֶׁל ״עָבַר יוֹם״. כָּךְ תִּרְגֵּם יוֹנָתָן: ״תֶּהֱווֹן דָּמַן לְכְמוֹצָא דְּנָשֵׁב בֵּיהּ רוּחָא, וּכִתְנָנָא דְּעָדֵי מִן קֳדָם יוֹמָא״. נֻסָּח אַחֵר: כְּטוּלָא דְּעָדוֹ וְכוּ׳״, זֶהוּ לְשׁוֹן ׳צֵל׳.",2,0],[2,4,"כִּי עַזָּה עֲזוּבָה תִהְיֶה. כִּי אִם תַּעֲשׂוּ כֵּן, אֶפְקֹד עַל שְׁכֵנֵיכֶם הָרָעִים – פְּלֶשֶׁת וְעַמּוֹן וּמוֹאָב, כְּמוֹ שֶׁהַנָּבִיא מְסַדְּרָן וְהוֹלֵךְ.",1,0],[2,4,"בַּצָּהֳרַיִם יְגָרְשׁוּהָ. אַשְׁדּוֹד שְׁמָהּ, וּבַצָּהֳרַיִם אֲשֶׁר יָשֹׁד בָּהּ קֶטֶב יְגָרְשׁוּהָ וּתְהִי שְׁדוּדָה. דָּבָר אַחֵר: בַּצָּהֳרַיִם יְגָרְשׁוּהָ – מְקוֹם מִרְעֵה צֹאן הָיָה, וְצָהֳרַיִם קָשֶׁה לָצֵאת בּוֹ צֹאן, וְכֵן הוּא אוֹמֵר: ״אֵיכָה תַּרְבִּיץ בַּצָּהֳרָיִם״ (שיר השירים א:ז).",2,0],[2,5,"חֶבֶל הַיָּם. ״סְפַר יַמָּא״. וּלְשׁוֹן ׳חֶבֶל׳ – מִדַּת הַקַּרְקַע הִיא, שֶׁמּוֹדְדִין בְּחֶבֶל. כְּלוֹמַר הַסְּמוּכִים לַיָּם.",1,0],[2,5,"גּוֹי כְּרֵתִים. תִּרְגֵּם יוֹנָתָן: ״עַמָּא דְמְחֻיָּבִין לְאִשְׁתְּצָאָה״. וּמִי הֵן יוֹשְׁבֵי חֶבֶל הַיָּם? כְּנָעַן אֶרֶץ פְּלִשְׁתִּים, כִּי פְּלִשְׁתִּים יוֹשְׁבִים עַל שְׂפַת הַיָּם הָאַחֲרוֹן בְּמַעֲרָבָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל, בְּתוֹךְ מִצְרֵי תְּחוּמֶיהָ. וְאַף שֶׁדּוֹרְשׁוֹ יוֹנָתָן לְכִלָּיָה, ״גּוֹי כְּרֵתִים״ – מְדִינָה הִיא בַּפְּלִשְׁתִּים וּשְׁמָהּ כְּרֵתִי. וְכֵן הוּא אוֹמֵר בְּצִקְלָג: ״אֲנַחְנוּ פָשַׁטְנוּ עַל נֶגֶב הַכְּרֵתִי וְעַל אֲשֶׁר לִיהוּדָה״ (שמואל א ל:יד), וְתִּרְגֵּם יוֹנָתָן: ״עַל דָּרוֹם כְּרֵתִי״. וּלְמַטָּה כָּתוּב: ״בְּכָל הַשָּׁלָל הַגָּדוֹל אֲשֶׁר לָקְחוּ מֵאֶרֶץ פְּלִשְׁתִּים וּמֵאֶרֶץ יְהוּדָה״ (שם ל:טז).",2,0],[2,6,"נְוֺת כְּרֹת רוֹעִים. נְוֵה עֲרַאי שֶׁיִּכְרוּ בָּהּ הָרוֹעִים לֶחֶם בַּבֹּקֶר. כְּרֹת לְשׁוֹן ״וַיִּכְרֶה לָהֶם כֵּרָה גְדוֹלָה״ (מלכים ב ו:כג).",1,0],[2,7,"וְהָיָה חֶבֶל לִשְׁאֵרִית בֵּית יְהוּדָה. וְהָיָה אוֹתוֹ הַגְּבוּל גּוֹרָל לִשְׁאֵרִית בְּנֵי יְהוּדָה. חֶבֶל זֶה לְשׁוֹן ׳גּוֹרָל׳ הוּא, וְכֵן תִּרְגֵּם יוֹנָתָן: ״וִיהֵי עַדְבָּא לִשְׁאָרָא דְבֵית יְהוּדָה״.",1,0],[2,8,"אֲשֶׁר חֵרְפוּ אֶת עַמִּי. כְּשֶׁהָיוּ מוֹלִיכִין יִשְׂרָאֵל בַּגּוֹלָה לְצַד אֶרֶץ כַּשְׂדִּים, וְהָיוּ עוֹבְרִין דֶּרֶךְ עַמּוֹן וּמוֹאָב, וְרוֹאִים יִשְׂרָאֵל בּוֹכִים וְגוֹנְחִים וְצוֹעֲקִין, הָיוּ מוֹנִין אוֹתָן וְאוֹמְרִים: מַה לָּכֶם לִהְיוֹת סְגוּפִים? מַה תִּבְכּוּ? הֲלֹא לְבֵית אֲבִיכֶם אַתֶּם הוֹלְכִים – ״בְּעֵבֶר הַנָּהָר יָשְׁבוּ אֲבוֹתֵיכֶם מֵעוֹלָם״ (יהושע כד:ב).",1,0],[2,8,"וַיַּגְדִּילוּ עַל גְּבוּלָם. וַיִּתְגָּאוּ עַל גְּבוּלָם.",2,0],[2,9,"כִּי מוֹאָב כִּסְדֹם תִּהְיֶה. גַּם אַתֶּם לְקַדְמַתְכֶם תָּשׁוּבוּ. לוֹט אֲבִיכֶם לֹא מִסְּדוֹם הָיָה?",1,0],[2,9,"מִמְשַׁק חָרוּל. הַשְׁמָעַת קוֹל, כְּמוֹ ״מַשַּׁק גֵּבִים״ (ישעיהו לג:ד). וְאַף מֵ״ם הָרִאשׁוֹנָה יְסוֹד הִיא בַּתֵּבָה, כְּמוֹ ״מִמְשַׁח הַסּוֹכֵךְ״ (יחזקאל כח:יד). ״מִמְשַׁק חָרוּל״ – הַשְׁמָעַת קוֹל חֲרוּלִים הַגְּדֵלִים שָׁם מֵאֵין עוֹבֵר, וְהֵן נוֹקְשִׁין זוֹ עַל זוֹ וּמַשְׁמִיעוֹת קוֹל.",2,0],[2,9,"וּמִכְרֵה מֶלַח. מְקוֹם כְּרִיַּת מֶלַח.",3,0],[2,11,"כִּי רָזָה. הִתִּישׁ כֹּחָם.",1,0],[2,11,"וְיִשְׁתַּחֲווּ לוֹ. כְּשֶׁיִּרְאוּ שֶׁנִּתְקַלְקְלוּ יִרְאָתָן.",2,0],[2,12,"גַּם אַתֶּם כּוּשִׁים. כְּשֶׁגָּלוּ שָׁם יִשְׂרָאֵל מֵעֵבֶר לְנַהֲרֵי כּוּשׁ.",1,0],[2,13,"עַל צָפוֹן. אַשּׁוּר בַּצָּפוֹן אֵצֶל בָּבֶל.",1,0],[2,13,"נִינְוֵה. הוּא רֹאשׁ לְאַשּׁוּר.",2,0],[2,14,"כָּל חַיְתוֹ גוֹי. כָּל בֶּהֱמוֹת הַגּוֹיִם.",1,0],[2,14,"קָאַת וְקִפֹּד. עוֹפוֹת.",2,0],[2,14,"בְּכַפְתּוֹרֶיהָ. פומל״ש שֶׁבְּרֹאשׁ הַגָּג.",3,0],[2,14,"חֹרֶב בַּסַּף. הַחֻרְבָּן יִהְיֶה נִכָּר בְּסִפֵּי הַבַּיִת.",4,0],[2,14,"קוֹל יְשׁוֹרֵר בַּחַלּוֹן. קוֹל הָעוֹפוֹת מְצַפְצְפִים בַּחֲלוֹנוֹת.",5,0],[2,14,"כִּי אַרְזָה עֵרָה. כִּי אֲרָזֶיהָ עִקֵּר וְשֵׁרַשׁ, כְּמוֹ ״עָרוּ עָרוּ״ (תהלים קלז:ז). וְיוֹנָתָן תִּרְגֵּם: ״וְטַלְלָהּ סָתְרוּ״ – הוּא גַּג הַבַּיִת הַסָּפוּן בְּאֶרֶז, שֶׁאֲפִלּוּ בָּתֵּי אֲבָנִים מְסַכְּכִין בִּנְסָרִים שֶׁל עֵץ.",6,0],[2,15,"וְאַפְסִי. וְאֶפֶס זוּלָתִי.",1,0],[3,1,"הוֹי מֹרְאָה וְנִגְאָלָה. עַד עַכְשָׁיו דִּבֵּר בְּנִינְוֵה, וְעַכְשָׁיו חוֹזֵר עַל יְרוּשָׁלַיִם: הוֹי, שֶׁתְּהֵא לְבַז וּלְסְחִי כְּרֹאִי, וּתְהֵא מְגֹאֶלֶת בִּצְחַן עֲוֹנָהּ. מֹרְאָה – כְּמוֹ ״מֻרְאָתוֹ״ (ויקרא א:טז), ״וְשַׂמְתִּיךְ כְּרֹאִי״ (נחום ג:ו).",1,0],[3,1,"הָעִיר הַיּוֹנָה. כְּיוֹנָה פּוֹתָה אֵין לֵב.",2,0],[3,3,"זְאֵבֵי עֶרֶב. הַמְּמַהֲרִים לֶאֱכֹל טַרְפָּם בַּלַּיְלָה.",1,0],[3,3,"לֹא גָרְמוּ לַבֹּקֶר. לֹא הִשְׁאִירוּ אַף הָעֲצָמוֹת לִגְרֹם לַבֹּקֶר.",2,0],[3,4,"חָמְסוּ תּוֹרָה. לֹא הוֹרוּ אוֹתָהּ לְשׁוֹאֲלֵיהֶם.",1,0],[3,5,"ה׳ צַדִּיק. הִשְׁרָה שְׁכִינָתוֹ בְּקִרְבָּם, וּלְפִיכָךְ אֵינוֹ יָכוֹל לִרְאוֹת בְּמַעֲשֵׂיהֶם הָרָעִים, כִּי צַדִּיק הוּא וְאֵין עַוְלָה לְפָנָיו.",1,0],[3,5,"מִשְׁפָּטוֹ יִתֵּן לָאוֹר. נוֹתֵן לָאוֹר, דָּן דִּין אֱמֶת לַאֲמִתּוֹ.",2,0],[3,5,"וְלֹא יוֹדֵעַ עַוָּל בֹּשֶׁת. וְכָל זֶה לֹא נָתְנוּ שׁוֹפְטֵי עָוֶל שֶׁבְּתוֹכָהּ אֶל לִבָּם לְהִתְבַּיֵּשׁ מִן הַצַּדִּיק הַשּׁוֹכֵן בֵּינֵיהֶם.",3,0],[3,6,"הִכְרַתִּי גוֹיִם. הֵבֵאתִי פֻּרְעָנוּת עַל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת כְּדֵי שֶׁתִּרְאוּ וְתִירָאוּ, כְּמוֹ שֶׁהוּא מְסַיֵּם וְהוֹלֵךְ: ״אָמַרְתִּי אַךְ תִּירְאִי אוֹתִי״.",1,0],[3,7,"וְלֹא יִכָּרֵת מְעוֹנָהּ. וְלֹא יֶחֶרְבוּן מְדוֹרֶיהָ.",1,0],[3,7,"כָּל אֲשֶׁר פָּקַדְתִּי עָלֶיהָ. וְלֹא יִכָּרֵת מִמֶּנּוּ כָּל הַטּוֹב אֲשֶׁר צִוִּיתִי לְהָבִיא עָלֶיהָ.",2,0],[3,8,"קוּמִי לְעַד. שֶׁאָקוּם לְהִתְוַעֵד עֲלֵיכֶם.",1,0],[3,10,"מֵעֵבֶר לְנַהֲרֵי כוּשׁ. יוֹבִילוּן לִי מִנְחָה.",1,0],[3,10,"עֲתָרַי. אֶת הַמִּתְפַּלְּלִין אֵלַי.",2,0],[3,10,"בַּת פּוּצַי. כְּנֵסִיּוֹת נְפוּצוֹתַי אֲשֶׁר הֲפִיצוֹתִי.",3,0],[3,11,"לֹא תֵבוֹשִׁי מִכָּל עֲלִילוֹתַיִךְ. כִּי כְּבָר לָקִית וְנִרְצָה עֲוֹנֵךְ.",1,0],[3,12,"עַם עָנִי וָדָל. עַם עַנְוְתָן וּמְקַבֵּל עֻלְבָּן.",1,0],[3,15,"מִשְׁפָּטַיִךְ. יִסּוּרֶיךְ, יושטיצ״א בְּלַעַ״ז.",1,0],[3,17,"גִּבּוֹר יוֹשִׁיעַ. גִּבּוֹר הוּא אֲשֶׁר יוֹשִׁיעַ מִן הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת.",1,0],[3,17,"יַחֲרִישׁ בְּאַהֲבָתוֹ. יְכַסֶּה עַל פְּשָׁעֶיךָ בְּאַהֲבָתוֹ, וְכֵן תִּרְגֵּם יוֹנָתָן: ״יִכְבּוֹשׁ עַל חוֹבֵךְ בְּרַחֲמָתֵיהּ״.",2,0],[3,18,"נוּגֵי מִמּוֹעֵד. אָסַפְתִּי אֶת הַמּוּצָאִים מִמּוֹעֲדֵי, שֶׁלֹּא הָיוּ מְשַׁמְּרִים שַׁבָּתוֹת וְיָמִים טוֹבִים.",1,0],[3,18,"אָסַפְתִּי. כִּלִּיתִי.",2,0],[3,18,"מִמֵּךְ הָיוּ. מֵעַמֵּךְ הָיוּ.",3,0],[3,18,"מַשְׂאֵת עָלֶיהָ חֶרְפָּה. עַל אוֹתָהּ אַשְׁמָה הָיָה לָךְ מַשְׂאֵת חֶרְפָּה.",4,0],[3,18,"נוּגֵי. לְשׁוֹן ׳הוֹצָאָה׳, כְּמוֹ ״הָגוֹ סִיגִים״ (משלי כה:ד), ״כַּאֲשֶׁר הוּגָה מִן הַמְּסִלָּה״ (שמואל ב כ:יג). וְאֵין שֹׁרֶשׁ בַּתֵּבָה אֶלָּא הַגִּימֶ״ל לְבַדָּהּ.",5,0],[3,19,"הִנְנִי עֹשֶׂה. תִּרְגֵּם יוֹנָתָן: ״הָא אֲנָא עָבֵיד גְּמִירָא״. וְיֵשׁ לְפוֹתְרוֹ לְשׁוֹן ׳עִ׳שּׂוּי׳, כְּמוֹ ״וְעַסּוֹתֶם רְשָׁעִים״ (מלאכי ג:כא).",1,0],[3,19,"בְּכָל הָאָרֶץ בָּשְׁתָּם. בְּכָל מָקוֹם אֲשֶׁר הָיוּ שָׁם לְבָשְׁתָּם, שָׁם אֶתְּנֵם לְשֵׁם וְלִתְהִלָּה.",2,0]]);
